mapper.select:
SELECT DISTINCT m.meetings_id, m.host_id, m.title, m.status, m.invite_code, m.default_lang, m.meeting_mode, m.scheduled_at, m.ended_at, m.created_at, m.is_private, CASE WHEN m.host_id = #{userId} THEN 'HOST' ELSE COALESCE(p.role, 'GUEST') END AS user_role, u.name AS host_name, u.email AS host_email, u.profile_image_url AS host_profile_image_url, u.locale AS host_locale, COALESCE(m.culture_desc, '') AS culture_desc, COALESCE(m.culture_desc, '') AS cultureDesc, COALESCE(m.culture_thumb_rel_path, '') AS culture_thumb_rel_path, COALESCE(m.culture_thumb_rel_path, '') AS cultureThumbRelPath FROM tl_meetings m LEFT JOIN tl_meeting_participants p ON m.meetings_id = p.meetings_id AND p.user_id = #{userId} LEFT JOIN tl_users u ON u.user_id = m.host_id WHERE (m.host_id = #{userId} OR p.user_id = #{userId})
AND m.status = #{status}
AND m.scheduled_at >= #{from}
AND m.scheduled_at <= #{to}
AND m.meeting_mode = #{mode}
ORDER BY m.scheduled_at DESC, m.meetings_id DESC LIMIT #{limit} OFFSET #{offset}

